SELECT *
FROM PM_VAT_O_VOC v
WHERE 1 = 1
AND next_action IN ('02','04')
AND rev_flag = '0'
AND MEDIA_TYPE = 'E'
AND (VOC_CHANNEL = '02' OR VOC_CHANNEL IS NULL)
AND ORG_ID = #{ORG_ID}

	AND VOC_TYPE = #{VOC_TYPE}


	AND VOC_FLAG  = #{VOC_FLAG}


	AND MADE_TYPE  = #{MADE_TYPE}


	AND VOC_STAT = #{VOC_STAT}


	AND VOC_DATE >= #{START_VOC_DATE}


	AND VOC_DATE <= #{END_VOC_DATE}


	AND VOC_NO >= #{START_VOC_NO}


	AND VOC_NO <= #{END_VOC_NO}


	AND CUST_NO = #{CUST_NO}

